```yaml
name: PR Title Check
on:
  pull_request:
    types:
      - opened
      - edited
      - synchronize

jobs:
  validate-pr-title:
    runs-on: ubuntu-latest
    steps:
      - name: Check PR Title Format
        uses: actions/github-script@v7
        with:
          script: |
            const prTitle = context.payload.pull_request.title;
            const prNumber = context.payload.pull_request.number;

            // Regular expression to match the required format: (TYPE) description [TASK-ID]
            const titleRegex = /^\([A-Za-z]+\)\s.+?\s\[[A-Z0-9]+-\d+\]$/;

            if (!titleRegex.test(prTitle)) {
              const errorMessage = `PR title "${prTitle}" does not match the required format: "(TYPE) description [TASK-ID]"`;
              core.setFailed(errorMessage);

              // Comment on the PR with the expected format
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: `❌ PR title does not match the required format: "(TYPE) description [TASK-ID]" \n\nExamples:\n- "(feat) add new feature [DA-123]"\n- "(fix) resolve bug [DA-456]"\n- "(chore) update documentation [DA-789]"`
              });
            } else {
              core.info(`✅ PR title "${prTitle}" matches the required format`);
            }
